export function stage3a2Text(locale: Locale, key: string) { return finalA2Labels[locale][key] || finalA2Labels.en[key] || durationAwareA2Labels[locale][key] || durationAwareA2Labels.en[key] || recoveryA2Labels[locale][key] || recoveryA2Labels.en[key] || dubbingFixLabels[locale][key] || dubbingFixLabels.en[key] || stage3a2Labels[locale][key] || stage3a2Labels.en[key] || key }

function interpolate(value: string, params?: Params) { return params ? value.replace(/\{\{(\w+)\}\}/g, (_, key: string) => String(params[key] ?? '')) : value }
type I18nValue = { locale: Locale; setLocale: (locale: Locale) => void; t: (key: string, params?: Params) => string; formatDuration: (seconds?: number) => string; formatDate: (value?: string) => string; friendlyError: (message: string) => { summary: string; details: string } }
const Context = createContext<I18nValue | null>(null)

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(() => { const saved = localStorage.getItem('ai-drama-locale'); return saved === 'en' ? 'en' : 'zh-CN' })
  const setLocale = (next: Locale) => { setLocaleState(next); localStorage.setItem('ai-drama-locale', next) }
  const value = useMemo<I18nValue>(() => ({ locale, setLocale, t: (key, params) => interpolate((locale === 'zh-CN' ? zh : en)[key] || en[key] || key, params), formatDuration: (seconds) => { if (typeof seconds !== 'number' || !Number.isFinite(seconds)) return locale === 'zh-CN' ? '\u8bfb\u53d6\u4e2d...' : 'Reading duration...'; const total = Math.max(0, Math.round(seconds)); const minutes = Math.floor(total / 60); const rest = total % 60; return locale === 'zh-CN' ? minutes ? `${minutes}\u5206${rest ? `${rest}\u79d2` : ''}` : `${rest}\u79d2` : `${minutes}:${String(rest).padStart(2, '0')}` }, formatDate: (value) => { if (!value) return locale === 'zh-CN' ? '\u672a\u77e5\u65e5\u671f' : 'Unknown date'; const date = new Date(value); if (Number.isNaN(date.valueOf())) return value; return date.toLocaleDateString(locale === 'zh-CN' ? 'zh-CN' : 'en-US', locale === 'zh-CN' ? { year: 'numeric', month: 'long', day: 'numeric' } : { month: 'short', day: 'numeric' }) }, friendlyError: (message) => locale === 'en' ? { summary: message, details: message } : /missing an original persisted reference|primary reference image|主参考图/i.test(message) ? { summary: '\u5f53\u524d\u89d2\u8272\u7f3a\u5c11\u539f\u59cb\u4e3b\u53c2\u8003\u56fe\uff0c\u8bf7\u4ece\u89c6\u9891\u622a\u5e27\u6216\u4e0a\u4f20\u56fe\u7247\u540e\u518d\u786e\u8ba4\u3002', details: message } : /network request failed|failed to fetch/i.test(message) ? { summary: zh['error.network'], details: message } : { summary: zh['error.requestFailed'], details: message } }), [locale])
  return createElement(Context.Provider, { value }, children)
}

export function useI18n() { const value = useContext(Context); if (!value) throw new Error('useI18n must be used inside LocaleProvider'); return value }

